import "core-js/modules/es.array.push.js";
import BaseLogin from "@/views/login/components/BaseLogin.vue";
import { adminLogin } from "@/utils/api";
import backgroundManager from "@/mixins/backgroundManager";
export default {
  name: "AdminLogin",
  components: {
    BaseLogin
  },
  mixins: [backgroundManager],
  data() {
    return {
      loginFields: [{
        key: "username",
        label: "用户名",
        placeholder: "请输入用户名",
        type: "text",
        icon: "user",
        show: true
      }, {
        key: "password",
        label: "密码",
        placeholder: "请输入密码",
        type: "password",
        icon: "lock",
        show: false
      }]
    };
  },
  mounted() {
    // 初始化背景图
    this.initializeBackground("adminLoginBkImg", ".login", true);
  },
  methods: {
    async handleLogin(formData) {
      await adminLogin(formData).then(({
        credentials
      }) => {
        this.$store.commit("base/setCredentials", credentials);
        this.$router.push("/dashboard");
      }).catch(error => {
        if (error.response && error.response.status === 401) {
          this.$message.error("用户名或密码错误");
        } else {
          this.$message.error("服务器错误");
        }
      });
    }
  }
};